INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold, no_change_condition) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-LAYER', '主估值层：盈利能力价值（Greenwald 三层）', '已形成建议', '腾讯音乐是轻资产平台：调整后的经营资产约 19 亿元，账面调整结果对无形资产和维持经营的现金假设敏感。增长能创造多少价值取决于优势能维持多久，而汽水音乐的免费模式（T3 观察）与多元变现（T4 存疑）都还没有定论。按 Greenwald 的顺序，以不增长的盈利能力价值作结论，增长价值只作为不付钱的上行空间：市价低于盈利能力价值时，买入不需要相信增长。', '每股价值与隐含回报都按盈利能力价值计算；资产价值、含增长价值在总览里并列展示，用于交叉检验。', '公司·主估值层', 'T3、T4 有了定论（付费用户与利润率在汽水音乐冲击下守住两年以上），可以改用含增长价值；利润率持续跌破 25% 时重新审视盈利能力本身。', '单季利润率波动、短期股价变化。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold, no_change_condition = EXCLUDED.no_change_condition;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-CASH', 'Q3 独立现金、债务及汇出税', '已形成建议', 'Q3 现金及存款 514.92 亿，扣经营周转 40.00 亿、融资和租赁负债 220.96 亿及暂估汇出税 21.70 亿。Q3 未单列投资应付款，保留在报表原科目内。汇出税沿用最近一次估算。', '第四层按 Q3 账面余额重算，与第一层使用同一期报表。', '收到境内未分派利润或投资应付款的新披露后复核。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-OPCASH', 'Q3 经营周转金暂估 40 亿元', '已形成建议', '一个月付款规模代理约 22 亿，加历史季节性波动缓冲约 10 亿及收入下降压力缓冲约 8 亿。按 Q3 营业成本与经营费用合计 66.50 亿估一个月规模，包含非现金费用。', '40 亿元从第四层现金池划入第一层。', '取得更细的月度付款和营运资金数据后复核。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-INV', 'Q3 投资统一按账面 80% 计入', '已形成建议', 'Q3 公允价值计量权益投资、权益法投资及其他流动与非流动投资合计 224.41 亿，按账面 80% 计 179.53 亿。20% 为处置税费、流动性与估值波动的合并估值假设。', '折后金额进入第四层。', '持仓结构、可变现性或税费变化后复核。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-AV', '资产价值：调整后的净经营资产（商誉不计入）', '已形成建议', '全公司口径（经营负债拆不到业务，不分业务估）。2026-09-30 报表口径的经营资本 287.4 亿元（经营资产 − 经营负债），加上划入的经营所需现金 40 亿元，合计 327.4 亿元，其中商誉 297.7 亿元。Q3 未单列投资应付款，整项其他应付款暂留经营。商誉不计入资产价值：它是收购溢价，不能单独变现，重建这门生意靠的是版权合作、用户与产品，不是这笔商誉。可辨认无形资产 55.50 亿元暂按账面 80% 计入，折减 11.10 亿元。Q3 未披露期末分类余额，折价是估值假设。调整后资产价值约 18.6 亿元。会员预收（递延收入）与应付版权费大于应收与存货，主营几乎不占营运资金。', '资产价值只用于第一层：与盈利能力价值比较时需考虑未入账的重建投入（含商誉基准 ROIC 约 28%，税后经营利润÷报表口径经营资本）；不进主估值。', '公司·资产价值口径；资产负债重估·商誉折价 100%、无形资产折价 20%', '大额并购或商誉减值；可辨认无形资产的构成披露变化。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
