INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-EPV', '调整后利润表：Greenwald 经营利润口径、收购摊销与所得税', '已形成建议', '遵循 Greenwald 第二层方法：从官方功能法核心经营利润出发，彻底剥离利息收入、一次性投资收益、联营损益与融资成本（均归入 ④ 单独计价）。税前仅加回七成非消耗性收购摊销（6.30 亿），三成并购版权摊销留作续约成本；股权激励（SBC 约 7 亿/年）作为真实股东成本不加回；零增长下的增长性营销/研发费用加回审慎取 0。所得税率取 2026 前三季度有效税率 16.9%（避开 2025 一次性免税收益扭曲）。', '收购摊销加回比例每变动 30 个百分点（±2.7 亿税前），影响可持续收益 E 约 ±2.2 亿元、每股 EPV 约 ±1.1 元。', '调整后利润表·七成收购摊销、所得税', '核心经营利润率持续偏离当前假设 2 个百分点以上，或年报披露收购摊销拆分（版权 vs 商标/技术）。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
