INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-EPV-MEMBER', '会员服务：并表后运行基线（不臆造已停披参数）', '已形成建议', '以 2026Q3 完整并表喜马拉雅后的会员收入 49.85 亿 × 4 ＝ 199.40 亿元作为零增长基线。会员按月续费、季节性弱，是最稳定的盈利锚；公司已自 2026Q1 停披季度付费用户与 ARPPU（2025Q4 为 1.274 亿 / 11.9 元），不人为倒推未验证的账户数与单价。核心变量是汽水音乐对存量留存的冲击与 SVIP 渗透。', '会员收入每下降 5%（约 −10.0 亿元），按集团税后净利率传导将减少 E 约 2.2 亿元（若按高毛利会员边际贡献约 40%+ 传导，影响更大、约 −3.2 亿元）。', '调整后利润表·会员服务收入', '年报披露年末付费用户低于 1.22 亿，或并表周年后可比会员收入转负。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
