INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-EPV-ADS', '营销及消费服务·广告：流量、填充率与渠道效率', '已形成建议', '与演出/周边合并在「营销及消费服务」中按滚动四季度（TTM 99.30 亿元）正常化，避免 Q1 淡季缺失造成的单季年化高估。2026H1 附注披露集团广告收入 25.24 亿、广告代理费 5.81 亿（约 23.0%），广告变现受免费广告版转化与宏观预算影响。', '营销及消费服务整体每下降 10%（约 −9.9 亿元），按当前净利率口径减少 E 约 2.2 亿元。', '调整后利润表·营销及消费服务', '广告负载大幅上升仍无增长，或核心品牌广告预算系统性流失。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
