INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-EPV-IP', '营销及消费服务·演出与周边：平滑季节性与头部艺人档期', '已形成建议', '2025 年营销及消费服务 Q1 仅 15.20 亿，Q2—Q4 约 24—25 亿；2026Q3 亦受汪苏泷合作拉动。采用 TTM 滚动四季度（99.30 亿元）替代 Q3×4（107.88 亿元），剔除约 8.6 亿元季节性与单季头部档期虚高。', '演出与周边毛利率低于会员订阅，若其占比继续扩大，须同步复核集团毛利率（当前已下修至 42.8%）。', '调整后利润表·营销及消费服务', '核心艺人巡演排期明显收缩、库存减值或集团毛利率跌破 42%。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
