INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-EPV-SOCIAL', '社交娱乐及其他：按同比下降后的最新运行底正常化', '已形成建议', '以 2026Q3 同比下降 15.7% 后的 12.59 亿 × 4 ＝ 50.36 亿元作无增长基线（低于 TTM 55.10 亿元），不假定直播打赏回升。', '收入较基准再降 20%（约 −10.1 亿元），由于主播分成可随收入同步缩减，对税前利润边际拖累约 1.5—2.0 亿元。', '调整后利润表·社交娱乐及其他', '监管收紧或公司主动关停导致单季同比跌幅扩大至 25% 以上。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-EPV-COST', '功能法经营成本与费用：锁定并表后 42.8% 毛利率与 25.6% 核心利润率', '已形成建议', '坚持官方功能法三线（营业成本 57.24%、销售费用 3.30%、管理费用 13.84%），保证 2021—2026Q3 历史连续、无黑箱差额，并直接对接 M1 护城河红线（毛利率 40%/42%）与 M4 腾讯生态获客优势（销售费用率 3.3% vs 网易云 7.5%）。三项比率全部取 2026Q3 完整并表后实绩，已主动低于 2025 顶点（毛利率 44.2%、核心经营利润率 29.4%）。2023—2026H1 附注按性质拆分（服务成本、员工福利、广告代理费、推广开支）在页面独立透视展示，供交叉核验。', '营业成本率或经营费用率每上升 1 个百分点，正常化 EBIT 减少约 3.49 亿元，每股 EPV 减少约 1.5 元。', '调整后利润表·营业成本、销售及营销费用、一般及行政费用', '单季毛利率连续两季低于 42%（T1 警戒线）或 40%（M1 证伪线）；销售费用率持续高于 4.5%。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
