INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-MCAP', '稳态配平：并表后经营折旧摊销 14.34 亿 ＝ 维持性资本开支 14.34 亿', '已形成建议', '2026Q3 折旧 0.53 亿 ＋ 无形摊销 4.63 亿，扣除已税前加回的七成收购摊销（1.575 亿）后年化为 14.34 亿元。2024—2025 年剔除一次性总部土地购置后，经营资本开支（10.32、11.88 亿）与同期折旧摊销（9.78、13.75 亿）基本 1:1 匹配。喜马拉雅并表后无形资产翻倍至 55.5 亿元，遵循 Greenwald 无增长稳态约束（真实经营折旧不能永续高于维持性资本开支），令维持性资本开支按 14.34 亿元配平（税后调整净额 0.00 亿元），杜绝跨期错配造成的 +52.5 亿元估值虚增。', '维持性资本开支每高于（或低于）经营折旧摊销 1 亿元，归母 E 减少（或增加）0.97 亿元，经营 EPV 变动 16.2 亿元（约 0.52 元/股）。', '调整后利润表·经营性折旧与摊销、维持性资本开支', '2026 年报披露并表后完整资本开支持续偏离经营折旧摊销 3 亿元以上（如 AI 算力/数据中心大幅扩张）。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
DELETE FROM vi_lnk_judgment_theses WHERE judgment_id = (SELECT id FROM vi_judgment_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'J-MCAP');
