INSERT INTO vi_judgment_base (company_id, code, title, status, judgment, transmission, parameter, change_threshold) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), 'J-MINOR', '少数股东 3%：经营部分乘 97%，非经营部分在桥里扣', '已形成建议', 'Q3 少数股东损益 0.65 亿÷净利润 22.19 亿，取整 3%（J-FIN）。经营部分：调整后利润表最后扣 3%，资产价值也乘 97%；非经营部分：资产负债桥只扣少数股东在非经营净资产（现金扣经营所需与有息负债、汇出预提税，对外投资折后，约 411.8 亿元）中的 3%，即 12.35 亿元。账面少数股东权益 28.39 亿元不全额扣：其余部分在经营资产里，已经被 97% 扣过，全额再扣就重复了。', '少数股东比例每 ±1 个百分点，每股盈利能力价值约 ∓0.4 元。', '调整后利润表·少数股东；资产负债重估·少数股东权益', '少数股东损益占比变化超过 1 个百分点（如喜马拉雅少数股东结构变化）。') ON CONFLICT (company_id, code) DO UPDATE SET title = EXCLUDED.title, status = EXCLUDED.status, judgment = EXCLUDED.judgment, transmission = EXCLUDED.transmission, parameter = EXCLUDED.parameter, change_threshold = EXCLUDED.change_threshold;
INSERT INTO vi_bs_item_base (company_id, category, line_item, name, haircut, adjustment, basis, sort) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), '经营资产', '物业厂房及设备', NULL, NULL, NULL, NULL, 1);
WITH ins AS (INSERT INTO vi_bs_item_base (company_id, category, line_item, name, haircut, adjustment, basis, sort) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), '经营资产', '无形资产', NULL, 0.2, NULL, '按账面 80% 暂计，折价 20% 是估值假设。2026Q3 披露期末 55.50 亿，较中报 58.95 亿减少 3.45 亿。中报附注 13 披露上半年企业合并新增 33.99 亿。2025 年报附注 15 的期初参照：版权 16.89 亿，域名、商标及牌照 4.30 亿，竞业协议 0.78 亿，企业客户关系 0.22 亿，供应商资源 0.01 亿，其他 6.79 亿。Q3 未披露期末分类余额。版权与牌照的重置成本取决于剩余期限、授权范围和续约条件；客户关系与竞业协议取决于存量客户留存及合同有效期。可按 0%、20%、50% 折价比较，待取得分类余额及合同资料后逐项重估。', 2) RETURNING id)
INSERT INTO vi_lnk_bs_item_judgments (bs_item_id, judgment_id, "createdAt", "updatedAt")
