WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, formula, method, value, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 1, '会员服务', '收入', '会员及订阅收入（附注）', '金额', 199.4, '2026Q3 官方披露 49.85 亿元 × 4 ＝ 199.40 亿元。会员按月续费、季节性弱，Q3 为喜马拉雅完整并表首季，直接作为无增长运行基线。公司自 2026Q1 起停披季度付费用户与 ARPPU（2025Q4 历史参照：1.274 亿付费用户、ARPPU 11.9 元），此处不臆造未披露参数。2025 年采用公司同口径比较数；2024 年及以前采用原音乐订阅口径。') RETURNING id)
INSERT INTO vi_lnk_epv_judgments (epv_id, judgment_id, "createdAt", "updatedAt")
SELECT ins.id, j.id, now(), now() FROM ins JOIN vi_judgment_base j ON j.company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND j.code IN ('J-EPV-MEMBER');
WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, formula, method, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 2, '营销及消费服务', '收入', '营销及消费服务收入', '滚动四季度', '采用近四季滚动合计（TTM 2026Q3 ＝ 99.30 亿元），而非 Q3 单季年化（107.88 亿元）。该板块含广告、线下演出与艺人周边，季节性显著（2025Q1 仅 15.20 亿，Q2—Q4 约 24—25 亿；2026Q3 亦受汪苏泷巡演拉动）。按 Greenwald 平滑周期与季节性原则，取完整四季滚动口径避免把旺季单季资本化。2024 年及以前采用在线音乐减订阅作历史参照。') RETURNING id)
INSERT INTO vi_lnk_epv_judgments (epv_id, judgment_id, "createdAt", "updatedAt")
SELECT ins.id, j.id, now(), now() FROM ins JOIN vi_judgment_base j ON j.company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND j.code IN ('J-EPV-ADS', 'J-EPV-IP');
WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, formula, method, value, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 3, '社交娱乐及其他', '收入', '社交娱乐服务及其他收入', '金额', 50.36, '2026Q3 官方披露 12.59 亿元 × 4 ＝ 50.36 亿元（同比 −15.7%）。直播打赏处于结构性收缩期，故意取低于近四季（55.10 亿元）的最新运行底作无增长基线，不假定回升。') RETURNING id)
INSERT INTO vi_lnk_epv_judgments (epv_id, judgment_id, "createdAt", "updatedAt")
SELECT ins.id, j.id, now(), now() FROM ins JOIN vi_judgment_base j ON j.company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND j.code IN ('J-EPV-SOCIAL');
WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, formula, method, value, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 4, '营业成本（版权、分成、演出与带宽）', '成本费用', '−营业成本', '占收入比例', 0.57241919, '取 2026Q3 完整并表后实绩：51.18 ÷ 89.41 ＝ 57.24%（对应毛利率 42.8%）。低于 2025 全年毛利率顶点（44.2%）与近四季（44.1%），已主动反映演出/周边低毛利占比上升及喜马拉雅长音频并表效应，避免把利润率高点当常态。2023—2026H1 附注按性质拆分见页面「成本性质透视」标签。') RETURNING id)
INSERT INTO vi_lnk_epv_judgments (epv_id, judgment_id, "createdAt", "updatedAt")
SELECT ins.id, j.id, now(), now() FROM ins JOIN vi_judgment_base j ON j.company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND j.code IN ('J-EPV-COST');
WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, formula, method, value, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 5, '销售及营销费用', '成本费用', '−销售及营销费用', '占收入比例', 0.03299407, '取 2026Q3 实绩：2.95 ÷ 89.41 ＝ 3.30%（高于 2025 年低点 2.86%）。已计入应对汽水音乐竞争的防守投放；依托腾讯生态仍显著低于网易云音乐（约 7.5%）。按 Greenwald 审慎原则，不假设零增长时销售费用还能继续压缩（增长性营销加回取 0）。') RETURNING id)
INSERT INTO vi_lnk_epv_judgments (epv_id, judgment_id, "createdAt", "updatedAt")
