WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, formula, method, value, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 6, '一般及行政费用（含研发、股权激励与收购摊销）', '成本费用', '−一般及行政费用', '占收入比例', 0.13835141, '取 2026Q3 完整并表后实绩：12.37 ÷ 89.41 ＝ 13.84%（高于 2025 年的 11.90%）。已全额计入喜马拉雅并表后的团队薪酬、研发投入、收购无形资产摊销及股权激励（SBC 约 7 亿元/年，属真实股东成本，绝不加回）。研发主要用于维持曲库分发与应对 AI/短视频竞争，增长性研发加回保守取 0。') RETURNING id)
INSERT INTO vi_lnk_epv_judgments (epv_id, judgment_id, "createdAt", "updatedAt")
SELECT ins.id, j.id, now(), now() FROM ins JOIN vi_judgment_base j ON j.company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND j.code IN ('J-EPV-COST');
WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, direction, method, value, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 7, '七成收购摊销（非消耗性 PPA）', '税前调整', '加', '金额', 6.3, '2026Q3 Non-IFRS 调节表披露收购无形资产摊销 2.25 亿元（年化 9.00 亿元）。按 Greenwald 经济实质区分：70%（6.30 亿元）对应商标、用户关系、技术等历史并购溢价分摊，维持现有业务无需重复购买，予以加回；余下 30%（2.70 亿元）对应并购取得的版权公允价值调整，合约到期需按市价续约，保留为真实经营成本。注：卖方 Non-IFRS 额外加回了约 7 亿元股权激励（SBC），本模型严格遵循 Greenwald 口径不予加回。') RETURNING id)
