WITH ins AS (INSERT INTO vi_epv_base (company_id, business_id, sort, name, section, direction, formula, method, value, note) VALUES ((SELECT id FROM vi_company_base WHERE code = '01698.HK'), (SELECT id FROM vi_business_base WHERE company_id = (SELECT id FROM vi_company_base WHERE code = '01698.HK') AND code = 'B1'), 10, '维持性资本开支（无增长稳态重置投入）', '税后调整', '减', '−购置物业厂房及设备 − 购置无形资产', '金额', 14.34, '无增长稳态下，按 Greenwald 原则令维持性资本开支与并表后经营性折旧摊销配平（14.34 亿元，净影响 0.00 亿元）。历史对照：2024—2025 年剔除一次性总部土地购置款后，经营资本开支为 10.32、11.88 亿元，与同期折旧摊销（9.78、13.75 亿元）基本 1:1 匹配。喜马拉雅并表后无形资产由 29.0 亿增至 55.5 亿、经营折旧摊销升至 14.34 亿；若错误沿用并表前 2022—2025 均值（11.09 亿）扣除，会凭空产生 +3.25 亿/年（折合 +52.5 亿元 EPV）的永续折旧虚增，违背无增长稳态资产不能折旧归零的经济学约束。') RETURNING id)
